import { existsSync, readFileSync } from 'node:fs'

// Every URL of the original site (generated by tools/import.mjs), so the static build covers pages nothing links to.
const readData = (name: string) => existsSync(`data/${name}`) ? JSON.parse(readFileSync(`data/${name}`, 'utf8')) : {}
const routes = Object.keys(readData('index.json')).map(encodeURI)
// Old URLs the WordPress site redirected; static builds emit a redirect page for each.
const redirects: Record<string, string> = readData('redirects.json')
const routeRules = Object.fromEntries(Object.entries(redirects).map(([from, to]) => [encodeURI(from), { redirect: { to: encodeURI(to), statusCode: 301 } }]))

// https://nuxt.com/docs/api/configuration/nuxt-config
export default defineNuxtConfig({
  compatibilityDate: '2026-10-01',
  modules: ['@nuxt/ui'],
  css: ['~/assets/css/main.css'],
  // Some original uploads start with "-", which Nuxt would otherwise skip when copying public/.
  ignorePrefix: '~skip-',
  ui: { fonts: false, colorMode: true },
  // Light stays the default so the site looks like the original until a visitor picks another mode.
  colorMode: { preference: 'light', fallback: 'light', storageKey: 'bp-color-mode' },
  app: {
    head: {
      htmlAttrs: { lang: 'fa-IR', dir: 'rtl' },
      meta: [{ name: 'viewport', content: 'width=device-width' }],
      // Declares the layer order before any stylesheet loads, so the legacy layer lands below Tailwind's base and utilities.
      style: [{ innerHTML: '@layer theme, base, legacy, components, elementor, utilities;', tagPriority: 'critical' }],
      // Applies the saved color theme before first paint (see composables/useSiteTheme.ts).
      script: [{ innerHTML: `try{var t=localStorage.getItem('bp-theme');if(t&&t!=='bekr')document.documentElement.dataset.theme=t}catch(e){}`, tagPriority: 'critical' }],
      link: [
        { rel: 'icon', href: '/wp-uploads/2019/07/cropped-LOGO-Right-Blue-1-32x32.png', sizes: '32x32' },
        { rel: 'icon', href: '/wp-uploads/2019/07/cropped-LOGO-Right-Blue-1-192x192.png', sizes: '192x192' },
        { rel: 'apple-touch-icon', href: '/wp-uploads/2019/07/cropped-LOGO-Right-Blue-1-180x180.png' },
      ],
    },
  },
  nitro: {
    serverAssets: [{ baseName: 'site', dir: '../data' }, { baseName: 'data', dir: '../public/_data' }],
    prerender: { crawlLinks: true, routes: ['/', '/sitemap.xml', ...routes, ...Object.keys(routeRules)], failOnError: false, concurrency: 8 },
  },
  routeRules,
  devtools: { enabled: false },
})
